import React, { useState, useEffect } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import ApiService from '../../Services/ApiService';
import { toast } from 'react-toastify';

export default function SellerProductReels() {
    const [reels, setReels] = useState([]);
    const [loading, setLoading] = useState(true);
    const [productName, setProductName] = useState('');
    const { productId } = useParams();
    const navigate = useNavigate();
    
    // Add state for filters
    const [filters, setFilters] = useState({
        product: '',
        category: '',
        date: ''
    });
    const [categories, setCategories] = useState([]);

    useEffect(() => {
        // Initialize Lucide icons
        if (window.lucide) {
            window.lucide.createIcons();
        }
        
        loadProductReels();
        loadCategories();
    }, [productId]);

    const loadCategories = async () => {
        try {
            const response = await ApiService.getCategories();
            if (response.success) {
                setCategories(response.data);
            }
        } catch (error) {
            console.error('Error loading categories:', error);
        }
    };

    const loadProductReels = async () => {
        try {
            setLoading(true);
            
            // Parse the product ID as integer
            const parsedProductId = parseInt(productId);
            
            if (isNaN(parsedProductId) || parsedProductId <= 0) {
                toast.error('Invalid product ID');
                setLoading(false);
                return;
            }
            
            // Get product name
            const productNamesResponse = await ApiService.getProductNamesByIds([parsedProductId]);
            if (productNamesResponse.success && productNamesResponse.data[parsedProductId]) {
                setProductName(productNamesResponse.data[parsedProductId]);
            } else {
                setProductName(`Product ${parsedProductId}`);
            }
            
            // Get seller reels from API
            const user = JSON.parse(localStorage.getItem('studioUser'));
            const vendorId = user?.vendor_id;
            
            if (!vendorId) {
                toast.error('Unable to load reels: User not authenticated');
                setLoading(false);
                return;
            }
            
            // Apply filters when loading reels
            const apiFilters = {};
            if (filters.product) apiFilters.product = filters.product;
            if (filters.category) apiFilters.category = filters.category;
            if (filters.date) apiFilters.date = filters.date;
            
            const response = await ApiService.getSellerReels(vendorId, apiFilters);
            
            if (response.success) {
                // Filter reels that contain this product ID
                const filteredReels = response.data.filter(reel => {
                    if (reel.product_ids && Array.isArray(reel.product_ids)) {
                        return reel.product_ids.some(id => {
                            const reelProductId = parseInt(id);
                            return !isNaN(reelProductId) && reelProductId > 0 && reelProductId === parsedProductId;
                        });
                    }
                    return false;
                });
                
                setReels(filteredReels);
            }
            setLoading(false);
        } catch (error) {
            console.error('Error loading product reels:', error);
            toast.error('Failed to load reels: ' + error.message);
            setLoading(false);
        }
    };

    const handleFilter = async () => {
        await loadProductReels();
    };

    const handleClearFilter = async () => {
        setFilters({
            product: '',
            category: '',
            date: ''
        });
        await loadProductReels(); // Reload all reels
    };

    const getStatusBadge = (status) => {
        switch (status) {
            case 'approved':
                return <span className="badge bg-success">Approved</span>;
            case 'pending':
                return <span className="badge bg-warning">Pending</span>;
            case 'rejected':
                return <span className="badge bg-danger">Rejected</span>;
            default:
                return <span className="badge bg-secondary">Unknown</span>;
        }
    };

    // Function to render video player for a reel
    const renderVideoPlayer = (reel) => {
        // Construct full URLs for video and thumbnail
        const baseUrl = window.location.origin;
        let fullVideoUrl = reel.video_url;
        let fullThumbnailUrl = reel.thumbnail;
        
        // Handle relative URLs
        if (reel.video_url && !reel.video_url.startsWith('http')) {
            fullVideoUrl = `${baseUrl}${reel.video_url}`;
        }
        
        if (reel.thumbnail && !reel.thumbnail.startsWith('http')) {
            fullThumbnailUrl = `${baseUrl}${reel.thumbnail}`;
        }
        
        if (!fullVideoUrl) {
            return <div className="alert alert-warning">No video available for this reel</div>;
        }
        
        return (
            <div className="video-player-container mb-4">
                <video 
                    width="100%" 
                    height="150" 
                    controls
                    poster={fullThumbnailUrl || ''}
                    className="rounded"
                >
                    <source src={fullVideoUrl} type="video/mp4" />
                    Your browser does not support the video tag.
                </video>
                <div className="mt-2">
                    <h6 className="mb-1">{reel.title}</h6>
                    <p className="text-muted small mb-1">
                        {getStatusBadge(reel.status)} | 
                        {reel.category_name && ` ${reel.category_name} | `}
                        {reel.created_at ? new Date(reel.created_at).toLocaleDateString() : 'N/A'}
                    </p>
                    <div className="d-flex justify-content-end">
                        {/* Modified View button to show only icon */}
                        <button 
                            className="btn btn-sm btn-outline-primary"
                            onClick={() => window.open(fullVideoUrl, '_blank')}
                            title="View Video"
                        >
                            <i className="ri-eye-line"></i>
                        </button>
                    </div>
                </div>
            </div>
        );
    };

    return (
        <div className="row">
            <div className="col-12">
                <div className="page-title-box d-flex align-items-center justify-content-between">
                    <h4 className="page-title mb-0">Reels for {productName}</h4>
                </div>
            </div>

            <div className="col-12">
                <div className="card">
                    <div className="card-header d-flex align-items-center justify-content-between">
                        <h5 className="card-title mb-0">Product Reels</h5>
                        <button 
                            className="btn btn-secondary" 
                            onClick={() => navigate(-1)}
                        >
                            <i className="ri-arrow-left-line me-1"></i> Back
                        </button>
                    </div>
                    <div className="card-body">
                        {/* Filter Section */}
                        <div className="row mb-3">
                            <div className="col-md-3">
                                <label className="form-label">Product Name</label>
                                <input
                                    type="text"
                                    className="form-control"
                                    placeholder="Filter by product name"
                                    value={filters.product || ''}
                                    onChange={(e) => setFilters({...filters, product: e.target.value})}
                                />
                            </div>
                            <div className="col-md-3">
                                <label className="form-label">Category</label>
                                <select
                                    className="form-select"
                                    value={filters.category || ''}
                                    onChange={(e) => setFilters({...filters, category: e.target.value})}
                                >
                                    <option value="">All Categories</option>
                                    {categories.map(category => (
                                        <option key={category.reel_category_id} value={category.reel_category_id}>
                                            {category.name}
                                        </option>
                                    ))}
                                </select>
                            </div>
                            <div className="col-md-3">
                                <label className="form-label">Date</label>
                                <input
                                    type="date"
                                    className="form-control"
                                    value={filters.date || ''}
                                    onChange={(e) => setFilters({...filters, date: e.target.value})}
                                />
                            </div>
                            <div className="col-md-3 d-flex align-items-end">
                                <div className="btn-group w-100" role="group">
                                    <button 
                                        className="btn btn-primary"
                                        onClick={handleFilter}
                                    >
                                        <i className="ri-filter-line me-1"></i> Filter
                                    </button>
                                    <button 
                                        className="btn btn-outline-secondary"
                                        onClick={handleClearFilter}
                                    >
                                        Clear
                                    </button>
                                </div>
                            </div>
                        </div>

                        {loading ? (
                            <div className="text-center py-5">
                                <div className="spinner-border" role="status">
                                    <span className="visually-hidden">Loading...</span>
                                </div>
                            </div>
                        ) : reels.length === 0 ? (
                            <div className="text-center py-5">
                                <h5>No reels found for this product</h5>
                                <p className="text-muted">There are no reels associated with {productName}.</p>
                                <button 
                                    className="btn btn-primary" 
                                    onClick={() => navigate(-1)}
                                >
                                    <i className="ri-arrow-left-line me-1"></i> Back to All Reels
                                </button>
                            </div>
                        ) : (
                            <div className="row">
                                {reels.map((reel) => (
                                    <div key={reel.id} className="col-md-6 col-lg-3 mb-4">
                                        {renderVideoPlayer(reel)}
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}
